const app=document.getElementById('app');if(!app.hasChildNodes())app.innerHTML=header()+(page==='home'?home():page==='checkout'?checkout():product(page))+footer()+drawer();
app.querySelectorAll('[data-course-pending]').forEach(button=>{button.disabled=false;button.removeAttribute('data-course-pending')});
const feedbackTimers=new Map();
document.querySelectorAll('[data-add]').forEach(button=>{
 button.dataset.label=button.textContent;button.classList.add('add-button');
 button.innerHTML=`<span class="add-label">${bagIcon}<span>${button.dataset.label}</span></span><span class="add-result" aria-hidden="true">${checkIcon}<span>Added</span></span>`;
});
function confirmAdd(button,changed){
 clearTimeout(feedbackTimers.get(button));
 button.querySelector('.add-result span').textContent=changed?'Added':'In cart';
 button.classList.add('is-added');button.setAttribute('aria-label',changed?'Added to your cart':'Already in your cart');
 button.focus({preventScroll:true});
 feedbackTimers.set(button,setTimeout(()=>{button.classList.remove('is-added');button.removeAttribute('aria-label');feedbackTimers.delete(button)},1800));
 if(changed&&!reducedMotion.matches)document.querySelectorAll('.cart-count').forEach(badge=>{badge.getAnimations().forEach(a=>a.cancel());badge.animate([{transform:'scale(1)'},{transform:'scale(1.2)',offset:.45},{transform:'scale(1)'}],{duration:240,easing:'ease-out'})});
}
function saveCart(){try{localStorage.setItem('ascore-courses-cart-v1',JSON.stringify(cart))}catch{}renderCart()}
function cartLine(id){const p=PRODUCTS[id];return `<article class="cart-line"><img class="cart-thumb" src="${p.image}" width="78" height="95" alt="${p.short} cover"><div><h3><a href="${p.path}">${p.short}</a></h3><p>${p.pages}-page PDF · ${money(p.price)}</p><button class="remove" data-remove="${id}" aria-label="Remove ${p.short} from cart">Remove</button></div></article>`}
function renderCart(){for(const [button,timer] of feedbackTimers){const ids=button.dataset.add==='both'?['meta','ai']:[button.dataset.add];if(!ids.every(id=>cart.includes(id))){clearTimeout(timer);button.classList.remove('is-added');button.removeAttribute('aria-label');feedbackTimers.delete(button)}}const focusedRemove=document.activeElement?.closest('[data-remove]');const focusInDrawer=focusedRemove?.closest('.drawer-panel');document.querySelectorAll('.cart-count').forEach(x=>x.textContent=cart.length);document.querySelectorAll('[data-open-cart]').forEach(x=>x.setAttribute('aria-label',`Open shopping cart, ${cart.length} ${cart.length===1?'course':'courses'}`));const total=cart.reduce((s,id)=>s+PRODUCTS[id].price,0);const empty='<div class="empty-cart"><h3>A little room to learn.</h3><p>Your cart is empty. Explore a course to get started.</p><a class="button ghost" href="/courses/#courses" data-close-cart>Explore courses</a></div>';document.getElementById('drawer-items').innerHTML=cart.length?cart.map(cartLine).join(''):empty;document.getElementById('drawer-bottom').innerHTML=cart.length?`<div class="cart-total"><span>Subtotal</span><span>${money(total)}</span></div><a class="button teal" href="/courses/checkout/">Review checkout</a><p class="cart-footnote">${cart.length===1?'One PDF':'Two PDFs'} · Checkout preview · Purchasing unavailable</p>`:'';if(page==='checkout'){document.getElementById('checkout-items').innerHTML=cart.length?cart.map(cartLine).join(''):empty;document.getElementById('checkout-total').innerHTML=cart.length?`<div class="cart-total"><span>Subtotal</span><span>${money(total)}</span></div>`:'';document.getElementById('review-order').disabled=!cart.length;document.getElementById('review-order').textContent=cart.length?'Review selection':'Add a course to continue';invalidateReview();syncCouponTotals()}if(focusedRemove){const target=focusInDrawer?(document.querySelector('.drawer-panel [data-remove]')||document.querySelector('.drawer-panel [data-close-cart]')):(document.querySelector('#checkout-items [data-remove]')||document.querySelector('#email'));target?.focus({preventScroll:true})}}
let lastFocus=null,lastAddButton=null;
function setBackgroundInert(value){[...app.children].filter(el=>!el.classList.contains('drawer')&&el.id!=='cart-status').forEach(el=>el.inert=value)}
function openCart(opener=document.activeElement){
 const d=document.getElementById('cart-drawer');if(d.classList.contains('open'))return;
 lastFocus=opener.closest('#toast')?(lastAddButton||document.querySelector('.cart-button')):opener;
 hideToast();d.inert=false;d.classList.add('open');d.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';setBackgroundInert(true);document.querySelector('.drawer-panel').focus({preventScroll:true});
}
function closeCart(){
 const d=document.getElementById('cart-drawer');if(!d.classList.contains('open'))return;
 d.classList.remove('open');d.setAttribute('aria-hidden','true');d.inert=true;document.body.style.overflow='';setBackgroundInert(false);hideToast();
 (lastFocus?.isConnected?lastFocus:document.querySelector('.cart-button'))?.focus({preventScroll:true});
}
let toastTimer;
function hideToast(){clearTimeout(toastTimer);const el=document.getElementById('toast');el.classList.remove('show');el.inert=true}
function scheduleToastHide(){clearTimeout(toastTimer);toastTimer=setTimeout(()=>{if(!document.getElementById('toast').matches(':hover,:focus-within'))hideToast()},5000)}
function toast(text){const el=document.getElementById('toast');document.getElementById('toast-message').textContent=text;document.getElementById('cart-status').textContent=text;el.querySelector('.toast-action').classList.toggle('hidden',!cart.length);if(!document.getElementById('cart-drawer').classList.contains('open')){el.inert=false;el.classList.add('show');scheduleToastHide()}}
const notice=document.getElementById('toast');notice.addEventListener('mouseenter',()=>clearTimeout(toastTimer));notice.addEventListener('focusin',()=>clearTimeout(toastTimer));notice.addEventListener('mouseleave',scheduleToastHide);notice.addEventListener('focusout',scheduleToastHide);
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){const ids=add.dataset.add==='both'?['meta','ai']:[add.dataset.add];let changed=false;for(const id of ids)if(!cart.includes(id)){cart.push(id);changed=true}saveCart();lastAddButton=add;confirmAdd(add,changed);const total=cart.reduce((sum,id)=>sum+PRODUCTS[id].price,0);toast(`${changed?'Added to your cart':'Already in your cart'} · ${money(total)}`);return}if(e.target.closest('[data-dismiss-toast]')){hideToast();lastAddButton?.focus({preventScroll:true});return}if(e.target.closest('[data-open-cart]'))openCart(e.target.closest('[data-open-cart]'));if(e.target.closest('[data-close-cart]'))closeCart();const remove=e.target.closest('[data-remove]');if(remove){remove.focus({preventScroll:true});cart=cart.filter(x=>x!==remove.dataset.remove);saveCart();toast('Course removed');return}const tab=e.target.closest('[data-lesson]');if(tab)selectLesson(tab.dataset.lesson)});
document.addEventListener('keydown',e=>{const d=document.getElementById('cart-drawer');if(d.classList.contains('open')){if(e.key==='Escape'){closeCart();return}if(e.key==='Tab'){const els=[...d.querySelectorAll('a[href],button:not([disabled]),[tabindex="0"]')];const index=els.indexOf(document.activeElement);const next=e.shiftKey?(index<=0?els.length-1:index-1):(index<0||index===els.length-1?0:index+1);e.preventDefault();els[next]?.focus({preventScroll:true})}}if(e.target.matches('[data-lesson]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const id=(e.key==='Home'||e.key==='End')?(e.key==='Home'?'meta':'ai'):(e.target.dataset.lesson==='meta'?'ai':'meta');selectLesson(id);document.getElementById('tab-'+id).focus()}});
function selectLesson(id){document.querySelectorAll('[data-lesson]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.lesson===id);b.tabIndex=b.dataset.lesson===id?0:-1});const c=document.getElementById('lesson-preview');c.setAttribute('aria-labelledby','tab-'+id);c.innerHTML=sampleContent(id)}
function invalidateReview(){reviewedKey='';const p=document.getElementById('payment-panel');if(p){p.classList.add('hidden');document.getElementById('step-review').classList.remove('active')}}
const cartKey=()=>[...cart].sort().join(',');
function syncCouponTotals(){
 if(page!=='checkout')return;
 if(appliedCoupon&&appliedCoupon.cartKey!==cartKey()){appliedCoupon=null;document.getElementById('coupon-message').textContent='Your cart changed. Apply the coupon again.'}
 const total=cart.reduce((sum,id)=>sum+PRODUCTS[id].price,0);
 if(appliedCoupon)document.getElementById('checkout-total').innerHTML=`<div class="coupon-totals"><p>Subtotal <span>${money(total)}</span></p><p>FREE coupon <span>−${money(total)}</span></p><div class="cart-total"><span>Total</span><span>AED 0</span></div></div>`;
 document.getElementById('apply-coupon').disabled=orderBusy||couponBusy||!cart.length;
}
async function courseRequest(path,{body,headers={}}={}){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);
 try{
  const response=await fetch('/api/courses'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...headers},...(body?{body:JSON.stringify(body)}:{}),signal:controller.signal});
  let data;try{data=await response.json()}catch{throw Error('Course checkout is temporarily unavailable. Please try again.')}
  if(!response.ok)throw Error(data.error||'Your order could not be confirmed. Please try again.');return data;
 }catch(error){if(error instanceof TypeError||error.name==='AbortError')throw Error('The connection was interrupted. Check delivery again using the same email and cart.');throw error}finally{clearTimeout(timer)}
}
if(page==='checkout'){
 const input=document.getElementById('email'),coupon=document.getElementById('coupon'),message=document.getElementById('coupon-message'),send=document.getElementById('send-free-order'),status=document.getElementById('order-status');
 const reviewKey=()=>JSON.stringify({email:input.value.trim().toLowerCase(),items:[...cart].sort(),coupon:appliedCoupon?.code||''});
 function lock(value){orderBusy=value;for(const el of [input,coupon,document.getElementById('apply-coupon'),document.getElementById('review-order'),...document.querySelectorAll('[data-remove],.cart-button')])el.disabled=value;send.disabled=value||!deliveryReady;document.getElementById('free-checkout').setAttribute('aria-busy',String(value));syncCouponTotals()}
 input.addEventListener('input',()=>{input.removeAttribute('aria-invalid');document.getElementById('email-error').classList.remove('visible');invalidateReview()});
 coupon.addEventListener('input',()=>{appliedCoupon=null;coupon.removeAttribute('aria-invalid');message.textContent='';renderCart()});
 document.getElementById('apply-coupon').addEventListener('click',async()=>{
  if(couponBusy||orderBusy||!cart.length)return;couponBusy=true;invalidateReview();message.textContent='Checking your coupon…';syncCouponTotals();const requested=cartKey();
  try{const q=await courseRequest('/quote',{body:{items:[...cart],coupon:coupon.value.trim()}});if(requested!==cartKey())throw Error('Your cart changed. Apply the coupon again.');if(q.coupon!=='FREE'||q.currency!=='AED'||q.totalMinor!==0||q.subtotalMinor!==cart.length*5000||q.discountMinor!==q.subtotalMinor)throw Error('The coupon could not be confirmed. Please try again.');appliedCoupon={code:'FREE',cartKey:requested};coupon.value='FREE';deliveryReady=q.freeCheckoutReady===true;message.textContent='FREE applied. Total AED 0. No payment required.';coupon.removeAttribute('aria-invalid')}
  catch(error){appliedCoupon=null;message.textContent=error.message;coupon.setAttribute('aria-invalid','true')}
  finally{couponBusy=false;renderCart()}
 });
 document.getElementById('checkout-form').addEventListener('submit',e=>{
  e.preventDefault();if(!cart.length||orderBusy||couponBusy)return;input.value=input.value.trim();const valid=input.validity.valid&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.value)&&input.value.length<=254;
  if(!valid){input.setAttribute('aria-invalid','true');document.getElementById('email-error').classList.add('visible');input.focus();return}
  reviewedKey=reviewKey();document.getElementById('review-email').textContent=input.value;const total=cart.reduce((sum,id)=>sum+PRODUCTS[id].price,0);document.getElementById('review-summary').textContent=`${cart.length} ${cart.length===1?'course':'courses'} · ${appliedCoupon?'FREE coupon · Total AED 0':'Subtotal '+money(total)}.`;
  document.getElementById('paid-checkout').classList.toggle('hidden',!!appliedCoupon);document.getElementById('free-checkout').classList.toggle('hidden',!appliedCoupon);send.textContent='Email my PDFs · AED 0';send.disabled=!deliveryReady;status.textContent=deliveryReady?'No payment is required. Your email will contain private links to your selected PDFs.':'Free course delivery is being prepared. Please try again later.';
  document.getElementById('payment-panel').classList.remove('hidden');document.getElementById('step-review').classList.add('active');document.getElementById('payment-panel').focus();
 });
 send.addEventListener('click',async()=>{
  if(orderBusy||!appliedCoupon||!deliveryReady||!reviewedKey||reviewedKey!==reviewKey())return;
  const key=reviewedKey,payload={email:input.value.trim().toLowerCase(),items:[...cart].sort(),coupon:'FREE'};lock(true);send.textContent='Preparing your email…';status.textContent='Saving your FREE order…';let accepted=false;
  try{
   const fingerprint=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(key)))].map(b=>b.toString(16).padStart(2,'0')).join('');let attempt;
   try{attempt=JSON.parse(sessionStorage.getItem('ascore-course-order-attempt-v1'))}catch{}
   if(!attempt||attempt.fingerprint!==fingerprint||(attempt.expiresAt&&Date.now()>=attempt.expiresAt)){attempt={fingerprint,id:crypto.randomUUID()};try{sessionStorage.setItem('ascore-course-order-attempt-v1',JSON.stringify(attempt))}catch{}}
   const order=await courseRequest('/orders',{body:{...payload,requestId:attempt.id}});attempt.receiptToken=order.receiptToken;attempt.expiresAt=order.expiresAt;try{sessionStorage.setItem('ascore-course-order-attempt-v1',JSON.stringify(attempt))}catch{}
   for(let n=0;n<25;n++){
    const result=await courseRequest('/orders/'+order.id,{headers:{'x-course-receipt':order.receiptToken}});
    if(result.delivery==='accepted'){accepted=true;status.textContent=`The mail provider accepted your download email for ${payload.email}. Order ${order.id}. Check your inbox and spam folder.`;break}
    if(result.delivery==='uncertain'){status.textContent=`Your FREE order is saved. Email delivery needs team review. Contact info@ascore.ae with order ${order.id}.`;break}
    if(result.delivery==='failed'){status.textContent=`Your FREE order is saved, but the email was not accepted. ${result.retryScheduled?'A safe retry is scheduled.':'Please contact the team for help.'} Contact info@ascore.ae with order ${order.id} if it does not arrive.`;break}
    status.textContent='Your FREE order is saved. Your download email is being prepared…';if(n===24)status.textContent='Your FREE order is saved. Email is pending; check your inbox shortly or check delivery again.';else await new Promise(r=>setTimeout(r,1000));
   }
  }catch(error){status.textContent=error.message}
  finally{lock(false);send.textContent=accepted?'Email accepted':'Check delivery';send.disabled=accepted||!deliveryReady}
 });
 const paidButton=document.getElementById('start-paid-checkout'),paidStatus=document.getElementById('paid-order-status');
 paidButton.addEventListener('click',async()=>{
  if(!paidReady||orderBusy||appliedCoupon||!reviewedKey||reviewedKey!==reviewKey())return;
  const key=reviewedKey;lock(true);paidButton.disabled=true;paidStatus.textContent='Preparing your payment page…';
  try{
   let attempt;try{attempt=JSON.parse(sessionStorage.getItem('ascore-paid-course-attempt-v1'))}catch{}
   if(!attempt||attempt.key!==key){attempt={key,requestId:crypto.randomUUID()};sessionStorage.setItem('ascore-paid-course-attempt-v1',JSON.stringify(attempt))}
   const result=await courseRequest('/paid/orders',{body:{requestId:attempt.requestId,items:[...cart],email:input.value.trim().toLowerCase()}});
   if(!result.id||!result.receiptToken)throw Error('Payment preparation needs team review.');
   attempt.id=result.id;attempt.receiptToken=result.receiptToken;sessionStorage.setItem('ascore-paid-course-attempt-v1',JSON.stringify(attempt));
   if(result.url){const next=new URL(result.url);if(next.protocol!=='https:')throw Error('Payment preparation needs team review.');window.location.assign(next.href)}
   else paidStatus.textContent='Payment preparation is pending. Contact Ascore before starting another attempt.';
  }catch(error){paidStatus.textContent=error.message}finally{lock(false);paidButton.disabled=!paidReady}
 });
 courseRequest('/config').then(config=>{deliveryReady=config.freeCheckoutReady===true;paidReady=config.paidCheckoutEnabled===true;paidButton.disabled=!paidReady;if(paidReady)paidButton.textContent='Continue to payment'}).catch(()=>{deliveryReady=false;paidReady=false});
 const returned=new URLSearchParams(location.search);
 if(['success','failure','cancelled'].includes(returned.get('payment'))){
  paidStatus.textContent='Returned from the payment page. This redirect does not confirm payment.';
  let attempt;try{attempt=JSON.parse(sessionStorage.getItem('ascore-paid-course-attempt-v1'))}catch{}
  if(attempt?.id===returned.get('order')&&attempt.receiptToken){
   courseRequest('/paid/orders/'+encodeURIComponent(attempt.id),{headers:{'x-course-receipt':attempt.receiptToken}}).then(result=>{
    paidStatus.textContent=result.paymentStatus==='paid'?(result.delivery==='accepted'?'Payment confirmed. The download email was accepted for delivery. Check your inbox.':'Payment confirmed. Course delivery is being checked.'):result.paymentStatus==='review'?'Payment needs team review. Contact info@ascore.ae.':'Payment is not confirmed. Contact Ascore before starting another attempt.';
   }).catch(error=>{paidStatus.textContent=error.message});
  }
  const panel=document.getElementById('payment-panel');panel.classList.remove('hidden');
 }
}
window.addEventListener('storage',e=>{if(e.key==='ascore-courses-cart-v1'){try{const data=JSON.parse(e.newValue||'[]');cart=[...new Set(Array.isArray(data)?data:[])].filter(x=>typeof x==='string'&&Object.hasOwn(PRODUCTS,x));renderCart()}catch{}}});
renderCart();if(page==='home')selectLesson('meta');
// The aligned layout stays stable: no entrance transforms or hidden content.

const preview=document.getElementById('preview-dialog');
let previewIndex=0,previewOpener=null,previewOverflow='';
function showPreview(index){
 const sample=PREVIEWS.meta[index];if(!sample)return;previewIndex=index;
 document.getElementById('preview-page').textContent=`Actual Meta PDF · Page ${sample.page} of 54`;
 document.getElementById('preview-title').textContent=sample.title;
 const img=document.getElementById('preview-image'),stage=preview.querySelector('.preview-stage');
 img.style.visibility='hidden';stage.setAttribute('aria-busy','true');img.src=sample.image;img.alt=`Actual course page ${sample.page}: ${sample.title}`;
 img.decode().then(()=>{if(previewIndex===index){img.style.visibility='';stage.setAttribute('aria-busy','false')}}).catch(()=>{if(previewIndex===index){stage.setAttribute('aria-busy','false');document.getElementById('preview-caption').textContent='This sample could not load. Close the preview and try the page link again.'}});
 document.getElementById('preview-caption').textContent=sample.note;
 document.getElementById('preview-position').textContent=`Sample ${index+1} of ${PREVIEWS.meta.length}`;
 preview.querySelector('[data-preview-prev]').disabled=index===0;
 preview.querySelector('[data-preview-next]').disabled=index===PREVIEWS.meta.length-1;
 preview.querySelector('.preview-stage').scrollTop=0;
}
document.addEventListener('click',e=>{
 const link=e.target.closest('[data-preview]');
 if(link){if(typeof preview.showModal!=='function')return;const [id,index]=link.dataset.preview.split(':');if(id!=='meta'||!PREVIEWS.meta[Number(index)])return;e.preventDefault();closeCart();previewOpener=link;previewOverflow=document.body.style.overflow;showPreview(Number(index));preview.showModal();document.body.style.overflow='hidden';preview.querySelector('[data-close-preview]').focus();}
 if(e.target.closest('[data-close-preview]'))preview.close();
 if(e.target.closest('[data-preview-prev]'))showPreview(previewIndex-1);
 if(e.target.closest('[data-preview-next]'))showPreview(previewIndex+1);
 if(e.target===preview){const r=preview.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)preview.close();}
});
preview.addEventListener('close',()=>{document.body.style.overflow=previewOverflow;previewOpener?.focus({preventScroll:true});});
preview.addEventListener('keydown',e=>{
 if(e.key==='Tab'){
  const controls=[...preview.querySelectorAll('button:not([disabled]),a[href],[tabindex="0"]')],index=controls.indexOf(document.activeElement);
  const next=e.shiftKey?(index<=0?controls.length-1:index-1):(index<0||index===controls.length-1?0:index+1);
  e.preventDefault();controls[next]?.focus({preventScroll:true});
 }
 if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();showPreview(previewIndex+(e.key==='ArrowRight'?1:-1));}
});
if(page==='meta'||page==='ai'){
 const sticky=document.querySelector('.sticky-buy'),heroAction=document.querySelector('.hero-add'),lastAction=document.querySelector('.final-cta');
 function updateSticky(){const r=heroAction.getBoundingClientRect(),last=lastAction.getBoundingClientRect();sticky.hidden=!(r.bottom<0&&!(last.top<innerHeight&&last.bottom>0));}
 const observer=new IntersectionObserver(updateSticky,{threshold:0});observer.observe(heroAction);observer.observe(lastAction);window.addEventListener('resize',updateSticky,{passive:true});updateSticky();
}
